-- Dams page (8_1): catchment rainfall month total (Aug 2026, served to 31 Aug: forward-filled from 1 Sep) and soil moisture month mean (Sep 2026); one row per district-day
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code FROM w) SELECT wl.code, round(sum(rainfall_mm_day)::numeric,1) rain_aug26, count(*) n FROM "8_1_reservoir_operational_master" t JOIN wl ON wl.lname=lower(t.district_name) WHERE date BETWEEN '2026-08-01' AND '2026-08-31' AND wl.code IN ('BUF','CPT','DC44','DC34') GROUP BY 1 ORDER BY 1;;
WITH {W}, wl AS (SELECT DISTINCT lower(name) lname, code FROM w) SELECT wl.code, round(avg(soil_moisture_m3_m3)::numeric,3) sm_sep26, count(*) n FROM "8_1_reservoir_operational_master" t JOIN wl ON wl.lname=lower(t.district_name) WHERE date BETWEEN '2026-09-01' AND '2026-09-30' AND wl.code IN ('BUF','CPT','DC44','DC34') GROUP BY 1 ORDER BY 1;;
SELECT date_trunc('month', date)::date m, count(DISTINCT rainfall_mm_day) nd_rain, count(DISTINCT soil_moisture_m3_m3) nd_sm FROM "8_1_reservoir_operational_master" WHERE date >= '2026-07-01' AND date <= CURRENT_DATE GROUP BY 1 ORDER BY 1;;
SELECT district_name, dam_name, river FROM "8_1_reservoir_operational_master" WHERE district_name IN ('Alfred Nzo','City of Cape Town','Vhembe') AND date = '2026-10-01';;
